fn get_min_val(a: &Vec<i8>) -> i8 {
    // Requires that the vector is non-empty
    // Ensures that the returned value is the minimum of the vector
    // Invariant: a is a non-empty vector
    assert!(!a.is_empty(), "Vector must not be empty");
    let min_val = *a.iter().min().unwrap();
    min_val
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Requires that the vector is non-empty
    // Ensures that the returned value is the maximum of the vector
    // Invariant: a is a non-empty vector
    assert!(!a.is_empty(), "Vector must not be empty");
    let max_val = *a.iter().max().unwrap();
    max_val
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Requires that the quantile q is between 0 and 100
    // Ensures that the returned value is the q-th quantile of the vector
    // Invariant: a is a vector of i8
    // Invariant: q is between 0 and 100
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");

    if q == 0 {
        return get_min_val(&a);
    } else if q == 100 {
        return get_max_val(&a);
    }

    let sorted = {
        // Invariant: sorted is a sorted version of a
        let mut sorted = a.clone();
        sorted.sort();
        sorted
    };

    // Invariant: sorted is a sorted vector of i8
    let index = (q as f64 / 100.0 * (sorted.len() as f64 - 1.0)).round() as usize;
    // Requires that index is within bounds of sorted
    assert!(index < sorted.len(), "Index must be within bounds of sorted vector");
    sorted[index]
}

